script:
frappe.ui.form.on('Segment Report', {
    agency: function(frm) {
        if (frm.doc.agency) {
            frappe.db.get_doc('Agency Contract', frm.doc.agency)
            .then(function(contract) {
                frm.set_value('agency_name', contract.agency_name);
                frm.set_value('account_manager', contract.account_manager);
            });
        }
    }
});

frappe.ui.form.on('Booking Measurement', {
    agency_contract: function(frm) {
        if (frm.doc.agency_contract) {
            frappe.db.get_doc('Agency Contract', frm.doc.agency_contract)
            .then(function(contract) {
                frm.set_value('agency_name', contract.agency_name);
                frm.set_value('account_manager', contract.account_manager);
                frm.set_value('contract', contract.contract);
            });
        }
    }
});

frappe.ui.form.on('Payment Tracking', {
    agency_contract: function(frm) {
        if (frm.doc.agency_contract) {
            frappe.db.get_doc('Agency Contract', frm.doc.agency_contract)
            .then(function(contract) {
                frm.set_value('agency_name', contract.agency_name);
                frm.set_value('account_manager', contract.account_manager);
            });
        }
    }
});

frappe.ui.form.on('Frontline Incentive', {
    agency_contract: function(frm) {
        if (frm.doc.agency_contract) {
            frappe.db.get_doc('Agency Contract', frm.doc.agency_contract)
            .then(function(contract) {
                frm.set_value('agency_name', contract.agency_name);
                frm.set_value('account_manager', contract.account_manager);
            });
        }
    },
    total_segments: function(frm) {
        calculate_total(frm);
    },
    rate: function(frm) {
        calculate_total(frm);
    }
});

function calculate_total(frm) {
    if (frm.doc.total_segments && frm.doc.rate) {
        frm.set_value('total_usd', frm.doc.total_segments * frm.doc.rate);
    }
}

frappe.ui.form.on('Zoho Import', {

    refresh(frm) {

        // ── زر Process Import ─────────────────────────────────────
        if (frm.doc.import_file && frm.doc.status !== 'Processing') {
            frm.add_custom_button(__('⚙️ Process Import'), () => {

                frappe.confirm(
                    __('سيقوم هذا الإجراء بقراءة الملف المرفق وإنشاء/تحديث سجلات Agency. هل تريد المتابعة؟'),
                    () => {
                        frappe.call({
                            method: 'sabre_finance.sabre_finance.api.process_zoho_import',
                            args:   { docname: frm.doc.name },
                            freeze: true,
                            freeze_message: __('⏳ جاري معالجة الملف، الرجاء الانتظار...'),
                            callback(r) {
                                if (r.message && r.message.status === 'success') {
                                    const m = r.message;
                                    frappe.msgprint({
                                        title:     __('✅ اكتملت عملية الاستيراد'),
                                        indicator: m.errors > 0 ? 'orange' : 'green',
                                        message: `
                                            <table class="table table-bordered" style="margin-top:8px">
                                                <tr><td><b>الصفوف المعالجة</b></td><td>${m.imported}</td></tr>
                                                <tr><td><b>وكالات جديدة</b></td><td>${m.new}</td></tr>
                                                <tr><td><b>سجلات محدّثة</b></td><td>${m.updated}</td></tr>
                                                <tr><td><b>صفوف متخطاة</b></td><td>${m.skipped}</td></tr>
                                                <tr><td><b>أخطاء</b></td><td>${m.errors}</td></tr>
                                            </table>
                                        `,
                                    });
                                    frm.reload_doc();
                                }
                            },
                        });
                    }
                );
            }, __('Actions'));
        }

        // ── لون مؤشر الحالة ──────────────────────────────────────
        const colors = {
            'Draft':                  'gray',
            'Processing':             'orange',
            'Completed':              'green',
            'Completed with Errors':  'yellow',
            'Failed':                 'red',
        };
        if (frm.doc.status) {
            frm.page.set_indicator(frm.doc.status, colors[frm.doc.status] || 'blue');
        }
    },

    // ── إعادة تهيئة الحقول عند إرفاق ملف جديد ──────────────────
    import_file(frm) {
        frm.set_value('status',        'Draft');
        frm.set_value('imported_rows', 0);
        frm.set_value('new_agencies',  0);
        frm.set_value('error_log',     '');
        frm.save();
    },
});
